contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(
        uint64 number_,
        uint64 timestamp_,
        uint256 basefee_,
        bytes32 hash_,
        uint64 seq_,
        bytes32 batcher_,
        uint256 overhead_,
        uint256 scalar_
    ) public payable {
        uint256 balBefore = address(c).balance;
        bool reverted;
        c.setL1BlockValues(number_, timestamp_, basefee_, hash_, seq_, batcher_, overhead_, scalar_); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(
            reverted &&
            address(c).balance == balBefore &&
            c.number() == 0 &&
            c.timestamp() == 0 &&
            c.basefee() == 0 &&
            c.hash() == bytes32(0) &&
            c.sequenceNumber() == 0 &&
            c.batcherHash() == bytes32(0) &&
            c.l1FeeOverhead() == 0 &&
            c.l1FeeScalar() == 0
        );
    }
    receive() external payable {}
}

