// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {L1Block} from "../src/L1Block.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    L1Block c;

    function setUp() public {
        c = new L1Block();
    }

    function _run(uint64 number_, uint64 timestamp_, uint256 basefee_, bytes32 hash_, uint64 seq_, bytes32 batcher_, uint256 overhead_, uint256 scalar_) internal {
        uint256 balBefore = address(c).balance;
        bool reverted;
        try c.setL1BlockValues(number_, timestamp_, basefee_, hash_, seq_, batcher_, overhead_, scalar_) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted &&
            address(c).balance == balBefore &&
            c.number() == 0 &&
            c.timestamp() == 0 &&
            c.basefee() == 0 &&
            c.hash() == bytes32(0) &&
            c.sequenceNumber() == 0 &&
            c.batcherHash() == bytes32(0) &&
            c.l1FeeOverhead() == 0 &&
            c.l1FeeScalar() == 0);
    }

    function testFuzz_run(uint64 number_, uint64 timestamp_, uint256 basefee_, bytes32 hash_, uint64 seq_, bytes32 batcher_, uint256 overhead_, uint256 scalar_) public {
        _run(number_, timestamp_, basefee_, hash_, seq_, batcher_, overhead_, scalar_);
    }

    receive() external payable {}
}
